item.aggregated_output:
  finish() {
    this.pinCompilerInputs();
    const artifact = this.artifact;
    artifact.entities = [...this.entities.values()]; artifact.relations = [...this.relationMap.values()];
    artifact.snapshot.files.sort((a, b) => compare(a.path, b.path));
    try {
      artifact.snapshot.commit = execFileSync('git', ['rev-parse', 'HEAD'], { cwd: this.root, stdio: ['ignore', 'pipe', 'ignore'], encoding: 'utf8' }).trim();
    } catch { /* Non-Git corpora have a null commit; content hashes still pin their inputs. */ }
    if (artifact.snapshot.commit) {
      // Scope Git reads to pinned inputs; large unrelated diagram stores can exceed maxBuffer.
      const paths = artifact.snapshot.files.filter(file => !file.path.split('/').includes('node_modules')).map(file => file.path);
      const gitPaths = new Set(paths);
      const options = { cwd: this.root, encoding: 'utf8' as const, maxBuffer: 16 * 1024 * 1024 };
      const tracked = new Set(execFileSync('git', ['ls-files', '-z', '--', ...paths], options).split('\0'));
      const changed = new Set(execFileSync('git', ['diff', 'HEAD', '--name-only', '-z', '--', ...paths], options).split('\0'));
      artifact.snapshot.dirtyFiles = artifact.snapshot.files.filter(file => gitPaths.has(file.path) && (changed.has(file.path) || !tracked.has(file.path)))
        .map(file => ({ path: file.path, status: tracked.has(file.path) ? 'modified' as const : 'untracked' as const, contentHash: file.contentHash }));
    }
    artifact.snapshot.id = `snapshot:${sha(JSON.stringify({ ...artifact.snapshot, id: undefined }))}`;
    for (const fact of [...artifact.entities, ...artifact.relations, ...artifact.uncertainties]) for (const range of fact.provenance.locations) range.snapshotId = artifact.snapshot.id;
    artifact.coverage.analyzedFiles = artifact.snapshot.files.filter(file => file.role === 'analyzed').length;
    artifact.coverage.resolutionOnlyFiles = artifact.snapshot.files.filter(file => file.role === 'resolution-only').length;
    artifact.coverage.unresolvedCount = artifact.uncertainties.filter(issue => ['unresolved', 'unsupported', 'ambiguous-identity'].includes(issue.kind)).length;
    for (const coverage of artifact.coverage.views) {
      // Derivable from persisted facts, so assembled and freshly extracted graphs
      // have exactly the same coverage accounting without hidden compiler state.
      const sites = { resolved: new Set<string>(), unresolved: new Set<string>() };
      const key = (range: AnalysisRange) => `${range.path}:${range.start.offset}:${range.end.offset}`;
      if (coverage.status !== 'not-run') {
        for (const edge of artifact.relations) if (edge.view === coverage.view) sites.resolved.add(key(edge.provenance.locations[0]));
        for (const issue of artifact.uncertainties) if (issue.view === coverage.view) sites.unresolved.add(key(issue.provenance.locations[0]));
      }
      coverage.unresolvedSites = sites.unresolved.size; coverage.resolvedSites = [...sites.resolved].filter(site => !sites.unresolved.has(site)).length;
      coverage.candidateSites = coverage.resolvedSites + coverage.unresolvedSites;
      if (coverage.unresolvedSites) coverage.status = 'partial';
    }
    return artifact;
  }

  /** Pin resolution inputs without retaining their compiler ASTs after release. */
  private pinCompilerInputs() {
    if (this.compilerInputsPinned || !this.activeProgram) return;
    this.compilerInputsPinned = true;
    const known = new Set(this.artifact.snapshot.files.map(file => file.path));
    const external: [string, string][] = [];
    for (const source of this.activeProgram.getSourceFiles()) {
      const relative = this.relative(source.fileName);
      if (known.has(relative)) continue;
      const contentHash = sha(source.text);
      if (relative.startsWith('../') || path.isAbsolute(relative)) { external.push([path.basename(source.fileName), contentHash]); continue; }
      this.compilerFileHashes.set(relative, contentHash); known.add(relative);
      this.artifact.snapshot.files.push({ path: relative, contentHash, utf16Length: source.text.length, lineCount: this.lineCount(source.text),
        role: 'resolution-only', language: relative.endsWith('.tsx') ? 'tsx' : relative.endsWith('.json') ? 'json'
          : relative.endsWith('.jsx') ? 'jsx' : relative.endsWith('.js') ? 'js' : 'ts' });
    }
    if (external.length) this.artifact.snapshot.analyzer.configurationHash = sha(JSON.stringify([
      this.artifact.snapshot.analyzer.configurationHash, external.sort(([a, ah], [b, bh]) => compare(a, b) || compare(ah, bh)),
    ]));
  }
}

import ts from 'typescript';
import { AnalysisContext, callable } from './context';
import type { AnalysisEntity } from '../../../domain/core/static-analysis/schema';

export class Declarations {
  readonly resolvedValues = new WeakMap<ts.Node, string | undefined>();
  readonly resolvedCallables = new WeakMap<ts.Node, string | undefined>();
  readonly receivers = new Map<ts.Node, string>();
  readonly declarationOwners = new Map<string, ts.Node>();
  readonly scopeBindings = new Map<string, Map<string, string>>();
  readonly parameterFields = new Map<ts.ParameterDeclaration, string>();
  readonly externalEntities = new WeakMap<ts.Node, Map<string, string>>();
  constructor(readonly ctx: AnalysisContext) {}

  name(node: ts.Node): string {
    const named = node as ts.NamedDeclaration;
    if (named.name && (ts.isIdentifier(named.name) || ts.isStringLiteral(named.name) || ts.isNumericLiteral(named.name))) return named.name.text;
    if (ts.isConstructorDeclaration(node)) return 'constructor';
    if (ts.isArrowFunction(node) || ts.isFunctionExpression(node)) {
      const parent = node.parent;
      if ((ts.isVariableDeclaration(parent) || ts.isPropertyDeclaration(parent) || ts.isPropertyAssignment(parent)) && ts.isIdentifier(parent.name)) return parent.name.text;
      return `<callback:${this.ctx.fingerprint(node).slice(0, 12)}>`;
    }
    return ts.SyntaxKind[node.kind];
  }
  structuralParent(node: ts.Node): string {
    let parent = node.parent;
    while (parent) {
      if (ts.isSourceFile(parent)) return this.ctx.module(parent);
      const known = this.ctx.nodeEntities.get(parent); if (known) return known;
      if (callable(parent) || ts.isClassDeclaration(parent) || ts.isInterfaceDeclaration(parent)) return this.ensure(parent);
      parent = parent.parent;
    }
    return this.ctx.rootId;
  }
  ensure(node: ts.Node, at: ts.Node = node): string {
    if (ts.isIdentifier(node) && node.parent && (ts.isBindingElement(node.parent) || ts.isParameter(node.parent)
      || ts.isVariableDeclaration(node.parent) || ts.isPropertyDeclaration(node.parent))) node = node.parent;
    if (!this.ctx.inside(node) || node.getSourceFile().isDeclarationFile && !this.ctx.selectedPaths.has(this.ctx.relative(node.getSourceFile().fileName))) {
      // External summaries belong to the referencing module. Sharing the first
      // caller's summary across modules makes unrelated files affect identity.
      const file = this.ctx.relative(at.getSourceFile().fileName);
      const summaries = this.externalEntities.get(node) ?? new Map<string, string>();
      const existing = summaries.get(file); if (existing) return existing;
      const name = this.name(node), module = this.ctx.module(at.getSourceFile());
      const filename = node.getSourceFile().fileName, relative = this.ctx.relative(filename);
      const origin = filename.includes('/node_modules/') ? filename.split('/node_modules/').pop()!
        : !relative.startsWith('../') && !relative.startsWith('/') ? relative : filename.split('/').pop()!;
      const id = this.ctx.addEntity('external', name, at, module, `external:${origin}:${name}`, 'external');
      summaries.set(file, id); this.externalEntities.set(node, summaries); return id;
    }
    const existing = this.ctx.nodeEntities.get(node); if (existing) return existing;
    if (ts.isSourceFile(node)) return this.ctx.module(node);
    const parent = this.structuralParent(node);
    let kind: AnalysisEntity['kind'] = 'binding';
    if (ts.isClassDeclaration(node) || ts.isClassExpression(node)) kind = 'class';
    else if (ts.isInterfaceDeclaration(node)) kind = 'interface';
    else if (ts.isTypeAliasDeclaration(node) || ts.isTypeParameterDeclaration(node)) kind = 'type';
    else if (ts.isConstructorDeclaration(node)) kind = 'constructor';
    else if (ts.isMethodDeclaration(node) || ts.isMethodSignature(node)) kind = 'method';
    else if (ts.isGetAccessorDeclaration(node) || ts.isSetAccessorDeclaration(node)) kind = 'accessor';
    else if (callable(node) || ts.isFunctionTypeNode(node)) kind = 'function';
    else if (ts.isParameter(node) || ts.isBindingElement(node) && this.isParameterBinding(node)) kind = 'parameter';
    else if (ts.isPropertyDeclaration(node) || ts.isPropertySignature(node) || ts.isPropertyAssignment(node)) kind = 'field';
    const name = this.name(node), anonymous = name.startsWith('<callback:');
    const id = this.ctx.addEntity(kind, name, node, parent, ts.isGetAccessorDeclaration(node) ? 'get' : ts.isSetAccessorDeclaration(node) ? 'set' : kind, 'source', anonymous);
    this.ctx.nodeEntities.set(node, id);
    const entity = this.ctx.entities.get(id)!;
    if (kind === 'interface' || kind === 'type') entity.metadata.namespace = 'type';
    else entity.metadata.namespace = kind === 'class' ? 'both' : 'value';
    if (kind === 'parameter') entity.metadata.bindingKind = 'parameter';
    if (ts.isVariableDeclaration(node) || ts.isBindingElement(node)) {
      let ancestor: ts.Node = node; while (ancestor.parent && !ts.isVariableDeclarationList(ancestor.parent) && !ts.isParameter(ancestor.parent)) ancestor = ancestor.parent;
      if (ancestor.parent && ts.isVariableDeclarationList(ancestor.parent)) entity.metadata.bindingKind = ancestor.parent.flags & ts.NodeFlags.Const ? 'const' : ancestor.parent.flags & ts.NodeFlags.Let ? 'let' : 'var';
    }
    if (ts.isImportSpecifier(node) || ts.isImportClause(node) || ts.isNamespaceImport(node)) entity.metadata.bindingKind = 'import';
    this.declarationOwners.set(id, node);
    return id;
  }
  isParameterBinding(node: ts.Node) { for (let parent = node.parent; parent; parent = parent.parent) { if (ts.isParameter(parent)) return true; if (ts.isVariableDeclaration(parent)) return false; } return false; }
  parameterField(node: ts.Node): string | undefined {
    if (!ts.isParameter(node) || !ts.isConstructorDeclaration(node.parent) || !ts.isParameterPropertyDeclaration(node, node.parent)
      || !ts.isIdentifier(node.name) || node.getSourceFile().isDeclarationFile) return undefined;
    const existing = this.parameterFields.get(node); if (existing) return existing;
    const owner = node.parent.parent, field = this.ctx.addEntity('field', node.name.text, node, this.ensure(owner), 'parameter-property');
    this.parameterFields.set(node, field); this.declarationOwners.set(field, node);
    this.ctx.entities.get(field)!.metadata.namespace = 'value';
    const scope = this.ctx.scopes.get(owner);
    if (scope) { this.ctx.bindingScopes.set(field, scope); this.ctx.edge('lexical', 'declares', scope, field, node); }
    this.ctx.edge('dependencies', 'value-flow', this.ensure(node), field, node, { mechanism: 'language' }, 'syntax');
    return field;
  }
  symbol(node: ts.Node): ts.Symbol | undefined {
    if (ts.isElementAccessExpression(node) && (ts.isStringLiteralLike(node.argumentExpression) || ts.isNumericLiteral(node.argumentExpression))) node = node.argumentExpression;
    const symbol = ts.isIdentifier(node) && ts.isShorthandPropertyAssignment(node.parent)
      ? this.ctx.checker.getShorthandAssignmentValueSymbol(node.parent) : this.ctx.checker.getSymbolAtLocation(node);
    if (!symbol) return undefined;
    if (symbol.flags & ts.SymbolFlags.Alias) { try { return this.ctx.checker.getAliasedSymbol(symbol); } catch { return symbol; } }
    return symbol;
  }
